def max_sliding_window(nums, k):
    if not nums or k <= 0:
        return []

    result = []
    for i in range(len(nums) - k + 1):
        current_max = nums[i]
        for j in range(i + 1, i + k):
            if nums[j] > current_max:
                current_max = nums[j]
        result.append(current_max)

    return result

